interface DitherPictureProps {
  /** Title-bar text, like a picture opened in a viewer. */
  caption: string
  className?: string
}

/**
 * Wetcast's dithered black-and-white sky (public/art/sky.png, generated by
 * docs/share/make_dither_art.py), framed as a small picture-viewer window with a status bar.
 * Decoration only: it is hidden from screen readers.
 */
export function DitherPicture({ caption, className = '' }: DitherPictureProps) {
  return (
    <figure aria-hidden="true" className={`r-window m-0 w-full max-w-[332px] ${className}`}>
      <div className="r-title">
        <span className="min-w-0 flex-1 truncate">{caption}</span>
      </div>
      <div className="r-sunken p-0.5" style={{ background: 'var(--field)' }}>
        <img src="/art/sky.png" width={320} height={180} alt="" className="r-dither-img block h-auto w-full" />
      </div>
      <div className="flex gap-0.5 pt-0.5 text-[0.92em]">
        <span className="r-status-field flex-1">320 × 180</span>
        <span className="r-status-field flex-1">2 colours</span>
      </div>
    </figure>
  )
}
